    'cli.doctor.sessions' => '已存储 {count} 个会话',
    'cli.doctor.settings_clean' => '所有设置文件仅包含 candy-code 读取的键',
    'cli.doctor.unknown' => '未知',
    'cli.headless.permission_hint' => '  提示：未指定模式的 `-p` 运行以询问式 `default` 模式启动；无人值守时无人应答，因此会安全失败。脚本运行可指定 --permission-mode bypass-permissions（或 accept-edits）以继续。',
    'cli.help.screen' => <<<'TXT'
CandyCode — 终端 AI 编程助手。

用法：
  candy-code                       启动交互式 TUI（默认）
  candy-code <dir>                 以 <dir> 为根启动 TUI，该目录必须
                                   存在（仅作为第一个参数）
  candy-code [<dir>] <words…>      启动 TUI 并将文字作为其
                                   首个提示发送，例如 candy-code fix the bug
  candy-code -c                    继续最近的会话
  candy-code --resume [<id>]       恢复已存储的会话（无 id 则显示选择器）
  candy-code -p <prompt>           运行单次提示并退出（一次性）
  candy-code run "<prompt>"        -p "<prompt>" 的别名（一次性模式）
  candy-code --output-format json  输出机器可读 JSON（一次性）
  candy-code --worktree [<name>]   在独立的 git worktree 中运行
                                   此会话（不存在则创建）

子命令（均不打开 TUI，也不需要提供商、API 密钥或
终端；除 serve 和 mcp serve 外，每个执行完即退出，
后者持续运行直到停止 — 而 attach 是两者的例外：它在运行中的服务器
会话上运行 TUI；acp 为编辑器运行轮次，直到编辑器断开）：
  bundles list           列出此目录可见的插件包：名称、
                         版本、层级，以及每个包携带的接口 —
                         包括 candy-code
                         拒绝运行的 hooks 和 .mcp.json。
  bundles install <src>  复制包目录，或以浅层克隆（深度为 1）
                         克隆 git URL 到用户包根目录
                         （~/.candy-code/bundles），仅你拥有。
  doctor                 检查此安装并报告发现的每个问题：
                         PHP 版本、会话存储和 serve 所需的扩展、
                         配置文件、权限策略、
                         所选提供商、会话数据库
                         和项目 MCP 配置。任何检查
                         失败则退出码为 1。
                         区别于模型可调用的 "doctor" 工具，后者
                         向模型报告终端的图像协议。
  import claude          预览导入 Claude Code 设置：读取 Claude 的用户
                         设置文件，以及启动根目录下的 .claude 设置文件，
                         当指定 --project 时，将其权限
                         allow/deny/ask 列表转换为 permissionRules（更严格的一方
                         始终优先——deny 胜过 allow），映射模型，并将所有
                         无法归类的键标记为 skipped。未经确认不写入任何内容：
                         --yes 直接接受打印的预览，
                         否则在交互式终端中询问。预览会列出
                         所有会扩大免确认运行范围的 allow 规则。
  login <provider>       登录一个提供商：claude-code 和 codex 将
                         终端交给其自身 CLI（令牌不会经过
                         candy-code）；openai、anthropic 和 gemini
                         将密钥粘贴到配置文件的 providers 块中；
                         其余则指明实际持有凭据的一方。
  models                 列出此安装可选的提供商及
                         各提供商的默认模型；"*" 标记当前
                         选中的提供商。
  session list [--all|--archived|--children] [--limit N]
                         列出已存储的会话，置顶优先，然后按最新
                         排序：id、最后更新、类型、轮次、provider/model
                         和名称（★ 标记置顶行）。--children 添加
                         子代理和后台行，--archived 添加
                         已归档行，--all 添加两者；默认 20 行，除非
                         --limit 另行指定。
  session show <target>  打印一个会话的详细信息和转录。
  session rename <target> <title…>
                         重命名会话；目标之后的文字即为
                         标题。
  session delete <target> [--with-children]
                         删除会话。子代理随之删除；
                         分支保留，除非指定 --with-children。
  session pin|unpin|archive|unarchive <target>
                         置顶会话（优先列出，永不清理），或
                         归档（从默认列表隐藏，仍保留）。
                         <target> 为 id、名称或唯一 id 前缀。
                         无匹配时退出码 1，前缀有歧义时退出码 2
                         （列出候选项）。
  mcp list               列出 .mcp.json 声明的 MCP 服务器，不
                         启动其中任何一个。若文件缺失、解析到项目树
                         之外，或存在但项目根未受信任，则报告
                         相应情况。
  mcp trust              按当前状态批准此项目的 .mcp.json：将
                         根目录加入 "trustedProjectMcp" 并记录每个
                         服务器的 command、args 和 env，此后任何变更
                         在启动时将被拒绝，直到重新批准。
                         不启动任何服务。
  mcp import claude|opencode|claude-project <path> [--write user]
                         转换外部 MCP 配置并将等效的
                         .mcp.json 块打印到 stdout。默认仅打印；
                         --write user 将转换后的条目追加到
                         用户自己的 ~/.candy-code/mcp.json
                         （名称冲突则拒绝整个写入，且
                         项目层永不写入）。转换中的重命名
                         列在 stderr 上。
  mcp serve [--root PATH]
                         通过 stdio 将 candy-code 本身作为 MCP 服务器
                         运行：每行一个 JSON-RPC 帧输入，每行一个响应
                         输出，直到 stdin 关闭。工具调用执行只读
                         工具集（Read、Glob、Grep、Ls、RepoMap），限制在
                         工作区根目录内，经过启动的 PermissionGate
                         和 PreToolUse 钩子链——这是客户端可启动的 MCP
                         服务器；WebSocket
                         `candy-code serve` 仍不支持 MCP。运行直到
                         停止。
  lsp install <language> 安装指定语言的固定版本语言服务器：
                         npm 包或经校验和验证的
                         发布二进制文件，安装到主目录下的私有
                         安装根目录。`lsp list` 可查询哪些语言
                         可安装。
  lsp list               报告所有可安装的语言：其固定
                         版本、服务器安装位置（或未安装），以及
                         此机器的操作系统和架构是否有对应
                         发布。不启动任何进程，
                         不下载任何内容。
  self-update [--check] [--rollback] [--allow-unsigned] [--channel=stable|dev]
                         用最新发布的 candy-code 版本替换此 phar
                         安装，交换前通过 sha256 对照发布
                         sidecar 验证；运行中的 phar 保留为
                         <phar>.old，--rollback 精确恢复该副本一次。
                         当发布源中固定了签名公钥时，
                         candy-code.phar.minisig
                         签名也必须通过验证（--allow-unsigned 仅跳过
                         该步骤）。--check 仅报告当前版本与最新版本
                         的差异，有更新时退出码 1。
                         Composer 安装将被明确拒绝，并提示
                         应运行的 composer update 命令。开发构建的
                         安装默认跟随滚动发布的 candy-code/dev
                         （当发布的目标提交与戳记的 sha 匹配时即为最新），
                         --channel 可显式选择
                         任一通道。
  serve [--host <ip>] [--port <n>] [--allow-remote] [--allowed-host <list>]
        [--allowed-ips <list>] [--allowed-origin <list>] [--allow-dir-browse]
        [--browse-root <dir>] [--web-root <dir>] [--no-web] [--allow-bypass]
        [--allow-root] [--detach] [--parent-pid <pid>]
        [--tls-cert <file>] [--tls-key <file>]
                         运行 Web UI 所连接的 WebSocket + HTTP 服务器，
                         在前台运行直至 Ctrl+C。默认绑定 127.0.0.1:7420
                         并打印一个登录 URL，其一次性代码
                         会换取浏览器 Cookie；每个客户端都需要它
                         或 ~/.candy-code/server/token 中的令牌，
                         包括回环地址。选项：
      --host <ip>        绑定地址（默认 127.0.0.1；localhost 和 ::1
                         也视为回环）。除非同时指定 --allow-remote，
                         否则拒绝其他地址。
      --port <n>         绑定端口（默认 7420；0 表示自动选择空闲端口）。
      --allow-remote     允许非回环 --host。若未指定 --tls-cert 和
                         --tls-key 则为明文 HTTP：请在前面放置 TLS 反向代理
                         或直接提供 TLS（见下文）。绑定
                         0.0.0.0 或 :: 时，服务器响应本机的所有
                         地址，登录 URL 中会列出它们。
      --tls-cert <file>  监听器自身用于提供 TLS 的 PEM 证书，
                         须与 --tls-key 一起指定。此时登录 URL
                         为 https://，会话 Cookie 携带 Secure 标志，
                         明文 http:// 客户端将得不到任何响应。
      --tls-key <file>   --tls-cert 对应的 PEM 私钥：文件须可读，
                         且组和其他用户无权限位，须与证书匹配。
                         无效或不完整的密钥对将在启动时拒绝。
      --allowed-host <list>
                         逗号分隔的额外主机名（或 host:port），
                         服务器将响应这些地址，例如本机的 DNS 名称。
                         可重复指定。
      --allowed-ips <list>
                         逗号分隔的允许连接的客户端 IP 或 CIDR 范围（如
                         1.2.3.4,10.0.0.0/8）；其他地址
                         在登录前即返回 403。回环地址
                         始终允许。未设置：不过滤地址。
                         可重复指定。
      --allowed-origin <list>
                         逗号分隔的额外浏览器来源
                         （http(s)://host[:port]），在服务器自身
                         来源之外允许。可重复指定。
      --allow-dir-browse 允许已登录客户端选择新会话的起始目录：
                         可在 --browse-root 下列出目录名（不显示
                         文件）。默认关闭。
      --browse-root <dir>
                         --allow-dir-browse 限定在此目录内
                         （默认为主目录）。
      --web-root <dir>   从 <dir> 提供 Web UI，而非已安装的
                         sugarcraft/candy-code-web 包。
      --no-web           仅提供 API 和 WebSocket，不提供 UI 文件。
      --allow-bypass     允许会话以 bypass-permissions 或 dont-ask
                         模式运行（默认拒绝；服务器的会话以
                         default 模式启动，除非 --permission-mode 另行指定）。
      --allow-root       允许以 root 身份运行（默认拒绝）。
      --detach           后台运行：端口绑定后打印一次 URL 和 pid
                         然后退出；服务器日志写入
                         状态目录中的 server.log。
      --parent-pid <pid> 进程 <pid> 退出时停止服务器（适用于
                         启动私有服务器的编辑器或 TUI）。
                         缺少 ext-pcntl、ext-posix 和
                         ext-ffi 时拒绝启动（参见 doctor）。端口被占用或
                         同一状态目录已有服务器运行时退出码为 1。
  serve status           报告运行中的服务器：pid、URL、根目录、运行时间以及
                         GET /api/health 是否有响应。无服务器运行时
                         退出码为 1。
  serve stop [--force]   停止服务器：发送 SIGTERM，最多等待 30 秒排空，然后 SIGKILL。
      --force            立即发送 SIGKILL。
  serve logs [-f]        打印后台服务器日志的末尾部分。
  -f, --follow           持续输出新增内容直至停止。
  serve url [--qr]       打印带新一次性代码的登录 URL。
      --qr              将每个登录 URL 渲染为可扫描的终端二维码。
  serve token [--rotate] 打印持有者客户端发送的 owner 令牌。
      --rotate           替换令牌；运行中的服务器保留旧令牌直到
                         重启。
  attach [<session>] [--url <url>]
                         在运行中的 candy-code serve 的会话上运行 TUI：
                         服务器执行每轮对话及其工具，
                         本终端显示它们并回答其提出的权限
                         问题。<session> 为服务器某个会话的 id、名称或
                         唯一 id 前缀；未指定时创建新会话。
                         服务器即 serve status 所报告的那个，其令牌取自
                         CANDY_CODE_SERVER_TOKEN 或状态目录的
                         令牌文件。退出时仅断开连接；运行中的轮次
                         继续执行。无服务器响应时退出码为 1。
      --url <url>        改为连接到 <url> 处的服务器（即 serve
                         打印的地址）。
  acp                    以 Agent Client Protocol 代理身份运行：编辑器
                         （Zed、JetBrains、Neovim）启动它并通过
                         stdin 和 stdout 进行 JSON-RPC 通信。会话在
                         其中打开
                         编辑器的项目根目录，轮次在此运行，使用此
                         安装的提供者和工具，编辑器回答
                         其权限问题。非终端模式：stdout
                         仅承载协议（其余输出至
                         stderr）。编辑器关闭 stdin 时退出码为 0。
  completion bash|zsh|fish
                         将 shell 补全脚本写入 stdout，例如
                         eval "$(candy-code completion bash)".
  usage [7|30|all] [--session <target>]
                         按天和模型汇总持久化消费账本：
                         与 `/usage` 页面输出相同，基于相同的共享
                         聚合。7 和 30 取整天（UTC），含当天，
                         all（或无操作数）覆盖整个账本，超出
                         该范围的窗口将被拒绝而非
                         静默扩大。--session 按 id、名称或唯一前缀
                         缩小到单个会话；--output-format json
                         输出页面构建所用的事实映射。
                         账本不可读时说明原因并退出码 1；
                         包含未定价模型的聚合中，金额
                         以 ≥ 下界显示，而非简单求和。

选项：
  -p, --prompt <text>    在命令行提供提示词（单次模式）
      --output-format <format>
                         输出格式："text"（默认）、"json" 或
                         "stream-json"（NDJSON 事件，答案在最后）
      --root <dir>       使用 <dir> 作为项目根目录，而非当前
                         目录。也接受 --root=<dir>（当 <dir>
                         以 "-" 开头时使用此形式）；不可省略。
                         在此和位置参数中同时指定根目录
                         将被拒绝，而非静默取其一。
      --config <file>    从 <file> 读取设置、权限和可信钩子根目录，
                         而非 ~/.candy-code/config.json。也
                         接受 --config=<file>。文件必须已存在、
                         可读、归你所有，且文件及其
                         目录均不可全局可写——它承载
                         权限策略，因此适用与
                         ~/.candy-code/config.json 相同的标准（/etc 或
                         /tmp 下的文件通常因上述原因被拒绝）。
                         仅移动该文件：agents、skills、workflows、
                         sessions 和 memory 仍位于 ~/.candy-code。
      --model <name>     使用 <name> 作为对话模型，覆盖
                         $CANDY_CODE_MODEL 和提供者的默认值。也
                         接受 --model=<name>。选择模型而非提供者
                         ——提供者仍来自 $CANDY_CODE_PROVIDER 或
                         持久化的 `provider` 设置，两者是
                         独立的维度。
      --permission-mode <mode>
                         以 <mode> 运行，而非配置文件中的模式
                         。也接受 --permission-mode=<mode>。最高
                         优先级：覆盖 $CANDY_CODE_PERMISSION_MODE 和
                         permissionMode 配置键。可选值：default、
                         accept-edits、plan、auto、dont-ask、
                         bypass-permissions。未设置时，TUI 和 -p
                         以 default 启动（写入和 shell
                         命令前会询问）；仅本地启动的守护进程
                         以 bypass-permissions 启动。
      --max-cost <usd>   将本次启动的报告消费上限设为 <usd> 美元：
                         超出上限的轮次将被拒绝
                         且不会发送。也接受 --max-cost=<usd>。
                         最高优先级：覆盖 $CANDY_CODE_MAX_COST 和
                         maxCostUsd 配置键。允许小数，
                         可带 $ 前缀（$2.50）；零和负值
                         将被拒绝而非视为"无上限"。/budget 仍可
                         提高或清除当前会话的上限。
      --max-turns <n>   将本次启动限制为 <n> 个工具循环步骤：用完
                         所有步骤的轮次将就地停止并说明。
                         也接受 --max-turns=<n>。最高优先级：
                         覆盖 maxToolSteps 设置键（此维度
                         无对应环境变量）。正整数；
                         零将被拒绝而非视为"无
                         上限"，无效值将拒绝启动
                         而非静默回退到设置值。
      --json-schema <path-or-json>
                         将答案约束为 JSON Schema：内联
                         {"type":"object",...} 文档或包含该文档的文件路径
                         。也接受 --json-schema=<value>；
                         当路径以 "-" 开头时使用 = 形式。
                         仅报告支持 schema 约束答案的
                         提供者才会执行请求——其他情况
                         以退出码 2 拒绝而非为无约束
                         答案计费。schema 约束轮次的
                         自完成请求；继续工具循环的步骤
                         不受约束（强制 JSON 答案无法
                         携带工具调用）。
      --append-system-prompt <text-or-@file>
                         将操作者规则追加到本次启动的系统
                         提示词：内联文本，或 @path 指向包含
                         规则的文件。也接受 --append-system-prompt=<value>；
                         当路径以 "-" 开头时使用 = 形式。
                         以 "-" 连接。规则作为额外的围栏
                         个人指令块到达，绝非覆盖：它们
                         不能替换或降级其上方的层级，且
                         文本中伪造的块标记会被中和。
                         大小限制与指令文档相同。
                         仅配合 -p 或 run 子命令使用：无
                         可追加提示词的启动将以退出码 2 拒绝，而非
                         静默忽略你提供的规则。
  -c, --continue         重新打开最近使用的会话（含完整记录），
                         而非新建会话。未指定时
                         每次启动都新建会话；在空输入框中按 Up
                         仍可回溯先前会话的提示词。
      --resume [<id|name>]
                         按 id、唯一 id 前缀或
                         名称（见 `session list`）重新打开已存储的会话。无值时，启动时打开
                         会话选择器；配合 -p 时目标为必填（记录将作为一次性
                         对话的种子，回答会写回该行）。也接受
                         --resume=<id>。不可与 --continue 组合使用。
                         --resume=<id>。不可与 --continue 组合使用。
      --worktree [<name>]
                         在 git worktree 中运行整个会话，
                         名为 main-<name>，分支为 candy-code/<name>，首次使用时创建；
                         未指定名称时自动选取。退出时，
                         无提交且无修改的 worktree 将被移除；
                         有工作的保留并输出其路径。
                         工作目录保留并报告其路径。已拒绝
                         在非 git 工作树中及 `serve` 旁使用时被拒绝。
      --incognito        无痕启动：不保存会话记录、不保存
                         对话记录、回合结束时不自动写入记忆。
                         运行产出仅存在于进程中；
                         此前已存储的会话和笔记仍可读。
                         不可与 --continue 或 --resume 同时使用（它们会重新打开
                         已保存的会话）。
      --restricted       受限启动：无法执行代码。Bash、PtyRun、Task、
                         Workflow、ShellStop 和 mcp_call 从整个会话的
                         所有面向模型的工具集中移除，且
                         /permissions 无法恢复。文件工具保留，
                         受现有路径限制约束。也接受
                         --restricted=true|false，使包装器可覆盖
                         携带裸标志的别名。重启后仍生效。
      --safe-mode        安全模式启动：忽略所有信任——每个受信任的
                         项目根目录均视为不受信任（hooks、项目
                         MCP 和命令 shell），不加载 bundle，不发现
                         外部 skills、commands 或 agents。
                         原生设置、skills 和 commands 保留。也接受
                         --safe-mode=true|false 以覆盖别名。
                         重启后仍生效。
  -h, --help             显示此帮助信息
  -v, --version          显示已安装版本并退出
      --                 选项结束：后续所有参数均为位置参数，
                         不再作为标志解析

环境变量：
   CANDY_CODE_PROVIDER    使用的提供商：openai、anthropic、claude-code、
                          sglang、bedrock、vertex、custom
   CANDY_CODE_MODEL       模型名称（覆盖提供商默认值；--model 优先）
   CANDY_CODE_PERMISSION_MODE
                          启动时的权限模式，覆盖
                          permissionMode 配置键（--permission-mode 优先）
   CANDY_CODE_BACKEND_CMD 自定义后端适配器的 shell 命令，遵循
                          PROSE 协议：从 stdin 接收 JSON 历史，将
                          回复文本写入 stdout，原样使用
                          （仅修剪首尾空白，因此内部的每个换行、空行
                          和缩进均保留）。
   CANDY_CODE_BACKEND_CMD_STREAM
                          同一 shell 调用，遵循另一协议——TOKEN
                          流：每行一个 token，两个 token 之间的换行
                          为帧分隔符并被丢弃，空行
                          为回复中的字面换行。回调随命令产出
                          每个 token 触发，但读取循环是同步的，
                          因此屏幕在结束时一次性重绘，
                          而非逐 token 刷新。与
                          CANDY_CODE_BACKEND_CMD 不可互换——将 prose
                          包装器通过此变量运行会导致所有
                          换行消失，每个空行合并为一行。
                          两者同时设置时 CANDY_CODE_BACKEND_CMD 优先。
                          对两者而言，未设置、空值和纯空白均视为
                          不存在。
   CANDY_CODE_DISABLE_PARALLEL_TOOL_CALLS
                          严格逐个执行回合内的工具调用。
                          并发调度为默认行为，且仅
                          组合非变更类工具；此变量为逃生开关。
                          可在
                          ~/.candy-code/config.json 中持久化为 "parallelToolCalls": false。
   CANDY_CODE_PARALLEL_TOOL_DEADLINE
                          并发组运行超时秒数，超时后
                          未完成的调用将被终止并报告为失败
                          （默认 90，须为 1-119；小数部分截断）。
                          持久化为 "parallelToolDeadlineSeconds"。
                          优先级：此变量 > 持久化键 >
                          则使用默认值。超出 1-119 范围的值，或
                          完全非数字的值，均不视为已设置——
                          会回退到下一个来源，而非
                          丢弃它。
   CANDY_CODE_ADVISOR_MODEL
                          `Advisor` 工具咨询以获取第二
                          意见的模型：无工具补全，计费方式与
                          其他调用相同。与 CANDY_CODE_TITLE_MODEL 不同，
                          无廉价回退——未设置则不
                          提供该工具。启动时读取。
   CANDY_CODE_TITLE_MODEL 用于在首次交互后自动命名会话的廉价模型；
                          默认使用提供商的模型。
   CANDY_CODE_SUMMARY_MODEL
                          撰写压缩摘要的模型；
                          默认使用对话自身的模型，以复用
                          提示缓存。
   CANDY_CODE_CONTEXT_PRUNING
                          auto、manual 或 off：会话如何修剪
                          上下文（当 /pruning 未选择时，默认 auto）。
   CANDY_CODE_MAX_COST    本次启动的支出上限，以美元计
                          （允许小数；接受前导 "$"；
                          --max-cost 优先）。超出上限的回合
                          将被拒绝。
   CANDY_CODE_CONNECT_TIMEOUT
                          连接阶段超时，以秒计（允许
                          小数；默认 15.0），用于提供商 HTTP
                          传输。仅限制建立连接
                          阶段——非请求总超时。已连接的流式服务器
                          发送响应头所需时间由单独的
                          streamHeaderTimeoutSeconds
                          设置项控制。
   CANDY_CODE_SEARCH_ENDPOINT
                          内置 WebSearch 工具查询的搜索 API。
   CANDY_CODE_SESSION_RETENTION_DAYS
                          正整数天数：每次启动删除
                          超过该时长未访问的会话。
   CANDY_CODE_SHARE_UPLOAD_URL
                          已弃用的上传主机：/share 不再上传
                          到任何地方。设置后，本地导出仍会生成，
                          但回复会明确拒绝该键并提示
                          /share serve，该命令在自托管的
                          candy-code serve 上发布快照页面。
   CANDY_CODE_WORKTREES_DIR
                          为每个队友创建 git
                          工作树的基础目录。
   CANDY_CODE_DISABLE_MOUSE
                          除空值或 0 外的任何值均关闭鼠标
                          追踪。
   CANDY_CODE_DISABLE_MOUSE_CLICKS
                          除空值或 0 外的任何值均忽略点击
                          手势，但保留滚轮滚动。
   CANDY_CODE_DISABLE_PROMPT_CACHE
                          除空值或 0 外的任何值均关闭
                          提供商提示缓存断点。
   CANDY_CODE_DISABLE_PROMPT_SUGGESTIONS
                          除空值或 0 外的任何值均停止每回合后
                          显示灰色下一条消息建议（→ 接受）。
   CANDY_CODE_DISABLE_AUTO_MEMORY
                          除空值或 0 外的任何值均停止自动记忆
                          将持久事实保存为笔记，以及
                          dream pass 将压缩日志
                          合并其中。
   CANDY_CODE_DISABLE_MODEL_METADATA
                          除空值或 0 外的任何值均停止读取和
                          刷新 LiteLLM 模型数据库（用于估算无内置
                          数据的模型大小和价格）。
   CANDY_CODE_NO_UPDATE_CHECK
                          除空值或 0 外的任何值均停止每日 phar
                          发布检查及其触发的启动更新通知；
                          不发出任何请求，过期的缓存
                          通知也不再显示。
   CANDY_CODE_DISABLE_SYMBOL_MAP
                          除空值或 0 外的任何值均将排序后的
                          符号映射排除在系统提示之外。
   CANDY_CODE_BACKGROUND  light 或 dark——强制自适应主题
                          对终端背景的判断，跳过
                          OSC 11 探测和 COLORFGBG。
   CANDY_CODE_DEBUG_SKILLS
                          除空值或 0 外的任何值均将 SkillLoader 的
                          逐跳过和逐拒绝目录日志输出到
                          stderr。
   CANDY_CODE_DEBUG_COMMANDS
                          除空值或 0 外的任何值均将 CommandLoader 的
                          发现拒绝日志输出到 stderr。
   CANDY_CODE_DEBUG_RULES 除空值或 0 外的任何值均将 RuleLoader 的
                          发现拒绝日志输出到 stderr。
   CANDY_CODE_DEBUG_STREAM
                          除空值或 0 外的任何值均保留 Chat 的
                          "onToken observer threw" 日志到 stderr。
                          detach 本身无论如何都会执行。
   CANDY_CODE_SERVER_HOST `serve` 绑定的地址（--host 优先）。
   CANDY_CODE_SERVER_PORT `serve` 绑定的端口（--port 优先）。
   CANDY_CODE_SERVER_ALLOWED_ORIGINS
                          逗号分隔的额外来源，`serve` 接受
                          （--allowed-origin 优先）。
   CANDY_CODE_SERVER_ALLOWED_HOSTS
                          逗号分隔的额外主机名，`serve` 响应
                          （--allowed-host 优先）。
   CANDY_CODE_SERVER_ALLOWED_IPS
                          逗号分隔的客户端 IP 或 CIDR，`serve` 允许
                          回环地址之外的（--allowed-ips 优先）。
   CANDY_CODE_SERVER_WEB_ROOT
                          `serve` 提供 Web UI 的目录（--web-root
                          优先）。
   CANDY_CODE_SERVER_TOKEN
                          `serve` 要求的令牌，替代其状态目录中的
                          令牌（至少 32 个字符；用于
                          容器）。
   CANDY_CODE_SERVER_DIR  `serve` 存放令牌、锁、
                          发现记录和日志的目录（默认
                          ~/.candy-code/server；以 0700 创建）。
   CANDY_CODE_SERVER_PARENT_PID
                          `serve` 随其停止的进程（--parent-pid 优先）。
   CANDY_CODE_MCP_DISABLE
                          1、true 或 yes（不区分大小写）完全禁用项目
                          MCP：.mcp.json 视为不存在，不启动
                          任何服务器。未设置、0 或其他值保持
                          MCP 启用——与标志类变量不同，
                          仅这三个词有效。
   CANDY_CODE_QUIET_LOGS  1、true 或 yes（不区分大小写）静默
                          error_log() 旁路通道（进程级，单一
                          输出端）；未设置、0 或其他值保持
                          诊断输出。仅启动时读取，无设置键。
   CANDY_CODE_REDUCED_MOTION
                          1、true 或 yes（不区分大小写）将代理
                          加载动画固定为单帧——面向动效敏感
                          及减少动效用户。启动时读取一次；
                          无设置键。
   CANDY_CODE_SD_BASE_URL A1111 风格（sdapi）Stable
                          Diffusion 服务器的基础 URL，媒体传输层连接此地址。
                          优先级：显式代码覆盖，然后此
                          变量，然后 sd.baseUrl 设置。
   CANDY_CODE_MEDIA_RENDER_MODE
                          生成图像在终端中的渲染方式
                          （ui.imageRenderMode 设置的环境层；参见
                          docs/ENVIRONMENT.md 获取可接受的值）。
   CANDY_CODE_ALLOW_ROOT_TESTS
                          设为 1 以允许 candy-code 测试套件
                          以 root 运行；未设置或其他值，套件
                          在 euid 0 时拒绝启动。不影响
                          candy-code 的启动——套件不是
                          面向用户的功能。
   CANDY_CODE_TOOL_INPUT  当前用户脚本工具调用的完整参数映射，
                          JSON 编码，导出到每个
                          ~/.candy-code/tools
                          工具运行时的子进程中；应用只写入不读取，
                          用户无需自行设置。
   CANDY_CODE_OTEL_BATCH_SIZE
                          每个 OTLP 导出批次包含的 span 数量
                          （默认 64，范围 1..2048）。
   CANDY_CODE_OTEL_TIMEOUT
                          每次 OTLP 导出尝试的超时秒数
                          （默认 3；非正值或格式错误的值
                          回退到默认值）。

   docs/ENVIRONMENT.md 列出了此构建读取的所有变量及其
   完整约定。

退出码（单次模式及所有子命令）：
  0                      提示词执行完毕并产生回答，或子
                         命令正常响应
  1                      执行失败：后端抛出错误（主机不可达、
                         密钥被拒、模型错误）——可重试——或
                         子命令执行失败（doctor 检查返回
                         FAIL，`session` 未找到对应会话，
                         受信任的 .mcp.json 无法解析）
  2                      用法或配置错误，未执行任何操作
                         且重试无效：未提供提示词、
                         无法识别的标志、裸参数未指向
                         已有目录（提示词需要 -p）、--root
                         未指向目录、缺少 composer
                         autoload.php，或所选 provider
                         无法构造——无论是
                         $CANDY_CODE_PROVIDER 还是
                         ~/.candy-code/config.json 中通过 Ctrl+P "Switch model" 持久化的 provider。
                         单次运行不会回退到离线 echo
                         provider（当已显式选择 provider 时）。
                         子命令收到缺失或未知的操作数
                         （`session`、`mcp bogus`、`completion tcsh`）也
                         报告于此。
  130/143/129             TUI：信号终止了循环 — 128+N 对应
                         SIGINT (Ctrl+C)、SIGTERM、SIGHUP；协作式
                         退出 (/exit, q) 仍以 0 退出。

示例：
  candy-code -p "解释 require 和 include 的区别"
  CANDY_CODE_PROVIDER=anthropic CANDY_CODE_MODEL=claude-sonnet-4-20250514 \
    candy-code -p "用 Go 写一个 hello world"
  candy-code run "用 Go 写一个 hello world"
  candy-code doctor
  candy-code models --output-format json | jq '.result.providers'
  eval "$(candy-code completion bash)"
  candy-code serve --port 7420

更多信息请参阅 README：
  https://github.com/detain/sugarcraft/tree/master/candy-code

