    'cmd.mcp-auth.login-done' => '✓ `{server}` 的 MCP 登录已完成（退出码 {code}）。令牌将在下次启动时附加 — 请启动新会话以使授权随请求发送；`/mcp list` 刷新面板。',
    'cmd.mcp-auth.login-failed' => <<<'TXT'
✗ `{server}` 的 MCP 登录以退出码 {code} 结束，未存储令牌。

子进程的最后几行见上方；在 shell 中执行相同流程（`candy-code mcp auth login {server}`）会打印完整错误，适合调试端点或端口问题。
TXT,
    'cmd.mcp-auth.login-failed-spawn' => "✗ 无法启动 `{server}` 的 MCP 登录子进程。\n\n直接运行 shell 命令：`candy-code mcp auth login {server}`。",
    'cmd.mcp-auth.login-guidance' => "交互式登录是 shell 命令，而非对话轮次：\n\n  candy-code mcp auth login <server> [token-url] [authorize-url] [registration-url]\n\n执行带 PKCE 的 OAuth 授权码流程：浏览器\n将授权码返回给 shell 中的回环监听器，存储的\n令牌将在下次启动时附加到匹配的 http 服务器。",
    'cmd.mcp-auth.login-no-entry' => "✗ 未找到本程序自身的入口点以 fork `mcp auth login {server}`。\n\n直接运行 shell 形式：`candy-code mcp auth login {server}`。",
    'cmd.mcp-auth.login-served-armed' => "↻ 已在 SERVER 主机上为 `{server}` 启动 MCP 登录——其链接将在下方显示；请在您本机的浏览器中打开。您的浏览器无法直接访问服务器的回环监听器：当页面显示连接错误时，复制该页面的地址并发送 `/mcp login {server} --code <that-url>` 将回调传递给等待中的登录。令牌将在下次启动时附加；`/mcp list` 在凭据存储后显示它。",
    'cmd.mcp-auth.login-url' => '→ 打开此 URL 以授权 `{server}`：\n\n  {url}',
    'cmd.mcp-auth.not-found' => '! 未找到 `{server}` 的凭据。',
    'cmd.mcp-auth.registered' => <<<'TXT'
✓ 已成功注册 `{server}`
客户端 ID：`{client}`
向具有此确切 URL 的 http MCP 服务器发出的请求现在会自动携带此令牌，到期前自动刷新；在此命令之前启动的服务器将在下次启动时获取它。
TXT,
