    'cmd.mcp-auth.usage' => "用法：\n  mcp auth list                    — 列出已注册的服务器\n  mcp auth add <server> [reg-url] [token-url]  — 存储服务器的 OAuth 凭据\n  mcp auth remove <server>         — 移除服务器的凭据\n  mcp auth login <server>          — 打印交互式登录的 shell 命令\n  /mcp reconnect                   — 重启已声明的服务器，仅在 .mcp.json 仍与启动时一致时\n  /mcp enable <server> [--persist]   — 解除本会话对已声明服务器的拒绝\n  /mcp disable <server> [--persist]  — 拒绝本会话中已声明服务器的调用",
