    // --- fix-app-launch 2026-10-14 ---
    'appLaunch.doctor.mbstring_missing' => '缺失 — 无法执行帧宽计算（mb_*）；请重新安装含 ext-mbstring 的 PHP',
    'appLaunch.doctor.intl_missing' => '缺失 — 无法执行字素/IntlChar 宽度计算；请重新安装含 ext-intl 的 PHP',
    'appLaunch.notice.policy_changed' => '⚠ config.json 或 hooks.yaml 自上次启动后已更改。新项目钩子仅在本次启动中保持隔离 — 请检查 ~/.candy-code/config.json 和 hooks.yaml，之后将生效',
    'appLaunch.notice.project_policy_changed' => '⚠ 受信任项目的 hooks.yaml 包含上次启动未见过的新条目。新项目钩子仅在本次启动中保持隔离 — 请检查该仓库的 .candy-code/hooks.yaml，之后将生效',
    'appLaunch.notice.bypass_mode' => '⚠ 权限模式为 bypass-permissions：所有工具调用无需确认即执行。可通过 /permissions（TUI）、--permission-mode 或在 ~/.candy-code/config.json 中设置其他权限模式来更改',
    // C-SEC-7.a: `-p` now defaults to the ASKING mode, so an unattended scripted
    // run that named no mode starts refusing — the launch says so once, and names
    // the one-flag fix. No trailing period — STDERR_LINE_FORMAT adds one
    // (LaunchNoticeOwnPeriodTest).
    'appLaunch.notice.headless_default' => 'ℹ -p 以默认权限模式启动：无人值守运行会拒绝所有需要确认的工具调用。脚本化运行请传入 --permission-mode（bypass-permissions 可执行全部操作）',
    // C-SEC-7.e (owner ruling t212, option 3): the implicit autoReview default
    // announces once per session the first time it engages — de-duped by message
    // identity in the launch-notices store, like the bypass banner. Names the
    // opt-out and owns up to the money. No trailing period — STDERR_LINE_FORMAT
    // adds one (LaunchNoticeOwnPeriodTest).
    'appLaunch.notice.auto_review_default' => '⚠ 本次启动默认开启 autoReview：被标记的自动模式调用将由标题模型审查，每次审查均为付费模型调用。在 ~/.candy-code/config.json 中将 autoReview 设为 false 可退出',
    // C-SEC-6.b: names the file, what it added, and what could not be honoured.
    // No trailing period — STDERR_LINE_FORMAT adds one (LaunchNoticeOwnPeriodTest).
    'appLaunch.notice.project_narrowing_rules' => '⚠ {file} 收窄了本次启动的权限：优先加载 {count} 条 deny/ask 规则，丢弃 {dropped} 条 allow 规则 — 项目文件不能授予 allow',
    'appLaunch.notice.restricted' => '⚠ --restricted：本次启动不含代码执行工具 — Bash、PtyRun、Task、Workflow、ShellStop 和 mcp_call 已从所有模型可用集中移除；文件工具仍受路径限制，且 /permissions 无法恢复被移除的工具',
    'appLaunch.notice.safe_mode' => '⚠ --safe-mode：本次启动忽略所有受信任的项目根目录、捆绑包及外部技能、命令和代理 — 行为等同于从未信任过任何内容',

    // --- fix-w2-chat 2026-10-14 ---
    'chat.launch.echo_backend' => '未配置任何提供方，本次会话使用内置离线回显后端 — 回复在本地回显，不调用模型。运行 `candy-code doctor` 查看提供方所需配置，配置完成后按 Ctrl+P 切换模型。',
    'keys.chat.repaint' => '清屏并重绘界面',
    'keys.unbound' => '未绑定',

    // --- C-EXT-1 (Claude Code hook dialect) 2026-10-27 ---
    'hooks.notice.advisory' => '⚠ `async` Claude Code 钩子 `{hook}` 退出码 {code}。`async` 钩子仅观察工具调用而非拦截，无权阻止，调用已继续执行。其输出：{reason}',
    'hooks.notice.claude_dialect' => '⚠ Claude Code 钩子 `{hook}` 退出码 {code}，Claude Code 将其视为非阻塞性警告而非决定，工具调用已继续执行。其输出：{reason}',
    'hooks.notice.said_nothing' => '（stderr 无输出）',
    'hooks.notice.system_message' => '⚠ 钩子 `{hook}` 留下了一条消息：{message}',

    // --- C-EXT-6.c (type: http hooks) 2026-10-30 ---
    // Every row names the hook and scheme://host only: never a path, a query,
    // or any header value, so an Authorization cannot ride out of the process
    // inside its own refusal.
    'hooks.http.deny_bad_url' => 'HTTP 钩子 `{hook}` 配置了不可用的 URL（{reason}）；显示的目标为 {target}。无法确定去向的钩子未批准此调用。',
    'hooks.http.deny_scheme' => 'HTTP 钩子 `{hook}` 指定了 {target}，不是 http 或 https URL。candy-code 仅通过这两种协议连接钩子，此调用被拒绝而非在未经验证的传输上执行。',
    'hooks.http.deny_credentials' => 'HTTP 钩子 `{hook}` 在 URL 中携带了凭据（{target}）。密码写入 URL 会出现在日志和代理中，因此此处拒绝；请改为通过请求头发送，其值引用 `allowedEnvVars` 中的名称。',
    'hooks.http.deny_blocked_target' => '无法查询 HTTP 钩子 `{hook}`：{reason}（{target}）。私有和链路本地地址按与出站请求相同的规则被拒绝，未到达的守卫未批准此调用。',
    'hooks.http.deny_unanswered' => 'HTTP 钩子 `{hook}` 未响应（{reason}）；目标为 {target}。无法到达的钩子未批准此调用，因此被拒绝。',
    'hooks.http.deny_header_injection' => 'HTTP 钩子 `{hook}` 无法发送 `{field}` 请求头：名称或值包含控制字符，属于请求帧而非请求头值。未向 {target} 发送任何内容，调用被拒绝。',
    'hooks.http.notice_unanswered' => '⚠ HTTP 钩子 `{hook}` 未响应（{reason}），无法拦截调用。请求地址为 {target}。',
    'hooks.http.reason_unreachable' => '连接或请求在钩子自身超时内超时',
    'hooks.http.reason_oversized' => '响应超过 {bytes} 字节且无有效结尾',
    'hooks.http.reason_no_status' => '响应不含 HTTP 状态行',
    'hooks.http.reason_redirect' => '发生了重定向，钩子调用不跟随重定向',
    'hooks.http.reason_status' => '响应非 2xx 状态',


    // --- C-EXT-6.d (type: prompt hooks) 2026-10-31 ---
    // Nothing was dialled and nothing was spent when these fire, so no row
    // carries a {target}: the hook either has no backend to be asked on, or
    // the answer it got is not a verdict.
    'hooks.prompt.deny_unanswered' => '提示钩子 `{hook}` 未响应（{reason}）。未返回裁决的钩子视为未批准，调用被拒绝。',
    'hooks.prompt.notice_unanswered' => '⚠ 提示钩子 `{hook}` 未响应（{reason}），无法拦截调用。',
    'hooks.prompt.reason_call_failed' => '无法向模型提问',
    'hooks.prompt.reason_empty_verdict' => '提示钩子 `{hook}` 拒绝了此调用，未给出原因。',
    'hooks.prompt.reason_no_backend' => '本次启动没有可询问的标题后端',
    'hooks.prompt.reason_no_prompt' => '条目包含空提示',
    'hooks.prompt.reason_unparseable' => '回复不是要求的含布尔 `ok` 字段的单个 JSON 对象',

    // --- settings help (W3-B i18n migration) ---
    'settings.advisorModel.help' => '`Advisor` 工具咨询的模型；未设置（默认）则不提供该工具（无廉价模型回退：必须是你选择的模型）。',
    'settings.allowedTools.help' => '工具名称或通配符白名单；未设置则提供所有工具。',
    'settings.attribution.help' => '{"commit": "…", "pr": "…"}：git 指南要求的尾注和 PR 行。',
    'settings.autoCommit.help' => 'off、turn（每轮一次提交，消息来自标题模型）或 edit（每次 Write/Edit 一次）；/undo 可撤销。',
    // C-SEC-7.e (owner ruling t212, option 3): the help states the implicit
    // default, the once-per-session announce, and the paid-call fact.
    'settings.autoReview.help' => 'auto 模式下，安全分类器标记的调用（安全发现除外，始终询问）由标题模型审查，可允许、询问或拒绝。存在可审查模型时默认开启，启用该默认的启动会提示一次；设为 false 可退出。每次审查均为付费模型调用。',
    'settings.autoReviewModel.help' => '自动审查器使用的 `provider/model`，例如 `openai/gpt-4.1-mini`；为空则使用标题模型。无法构建的提供程序会关闭审查器并发出启动警告。',
    'settings.autoReviewScope.help' => '`autoReview` 发送给审查器的内容：`shell`（默认）为模式列表通过的所有非只读 shell 命令；`writes` 还审查 `Edit`、`Write`、`ApplyPatch` 和 `WebFetch`，写入工具附带待处理差异；`all` 审查列表通过的所有调用。其他拼写等同于 `shell`。每次审查均为付费模型调用。',
    'settings.autoTest.help' => '编辑文件后运行 `testCommand`；失败时将输出回传模型，每轮最多 3 次。',
    'settings.bashInteractiveIdleSeconds.help' => '`interactive: true` 的 Bash 运行允许无输出的秒数，超时则视为等待按键而停止。',
    'settings.bashMaxTimeoutSeconds.help' => 'Bash 命令可请求的最大 `timeout`；超出值将被截断。',
    'settings.bashSandbox.help' => 'Linux 在 bubblewrap 中运行 Bash；macOS 通过 `sandbox-exec` 在 Seatbelt 配置文件中运行——仅工作根目录可写（`no-network` 还会切断网络）。`allowlist`（Linux）将网络出口路由到启动的出口代理，仅允许 `sandboxAllowedDomains` 中列出的主机：默认空列表时行为与 `no-network` 完全相同，即使列出主机，非 HTTP 流量（ssh、数据库端口）和未列出的主机仍会失败。macOS 上 `allowlist` 按 `no-network` 执行。沙箱无法启动时拒绝命令；无法识别的值等同于 `no-network`，绝不会是 `off`。',
    'settings.bashSandboxNestedUserns.help' => '设为 `true` 允许沙箱化 `Bash` 命令创建自己的用户命名空间，rootless podman、buildah 和 Chromium 沙箱需要此功能。默认 `false` 以 `--unshare-user --disable-userns` 运行 bubblewrap，阻止从挂载沙箱逃逸的常见途径；若主机的 bubblewrap 版本过旧不支持这些标志，沙箱将以基本模式运行并在其描述中说明。',
    'settings.bashTimeoutSeconds.help' => '模型未传 `timeout` 时 Bash 命令可运行的秒数；不超过 Bash 上限。',
    'settings.chatToolTimeoutSeconds.help' => 'chat-native（`command` 提供程序）路径分叉的工具调用批次的挂钟预算；超时者将被终止。',
    'settings.claudeMcpArgs.help' => '该二进制的参数；未设置则使用传输默认值。',
    'settings.claudeMcpBinary.help' => 'claude-mcp 传输可启动的 `claude` 二进制文件的绝对路径。',
    'settings.claudeMcpEnv.help' => '传递给该二进制文件的环境变量。',
    'settings.compaction.autoPercent.help' => '发送提示前自动压缩较早对话的窗口占比。',
    'settings.compaction.autoTokens.help' => '自动层级和轮内步骤预算的绝对上限。0 表示无上限。',
    'settings.compaction.blockPercent.help' => '超过此窗口占比时拒绝提示直到释放空间；唯一会拒绝的层级。',
    'settings.compaction.blockTokens.help' => '阻塞层级的绝对上限；默认未设置。设置后该上限可拒绝提示。',
    'settings.compaction.idleAuto.help' => '空闲期间自动压缩超出层级的会话，而非等待下一次提示，使用自动层级的机制（受花费上限和抖动断路器约束）。off：从不；hour：在完整的 compaction.idleOfferSeconds 窗口之后；cacheTtl：在提供程序的提示缓存过期前——提供程序标记缓存断点时为一小时，服务端缓存约为 5 分钟，未报告缓存时从不——当历史超过自动层级下限一个阈值时，否则下一次提示将无缓存地预填充整个对话；在 60 秒刻度上，5 分钟缓存约在 4 分钟空闲时折叠。需要一次后台提供程序调用；要求 compaction.idleOfferSeconds 大于 0。布尔值仍可读：true 等同于 hour，false 等同于 off。',
    'settings.compaction.idleOfferSeconds.help' => '超出整个上下文窗口且空闲超过此时长的会话将提示 /compact 而非发送提示。0 表示从不提示。',
    'settings.compaction.keepRecent.help' => '压缩时完整保留的最近用户/助手对话轮数。',
    'settings.compaction.mode.help' => 'llm：摘要模型撰写摘要（启发式为回退）；heuristic：本地单行摘要，不调用模型；off：不自动压缩，/compact 仍可用，阻塞层级仍会拒绝。',
    'settings.compaction.modelTokenCaps.help' => '{"<model>" 或 "<provider>/<model>": {"reminderTokens", "autoTokens", "blockTokens"}} 覆盖三个上限；0 清除对应项。',
    'settings.compaction.refillLimit.help' => '连续自动压缩次数，超过后下一次提示将被拒绝而非再次压缩（提示未发送即超出层级）。',
    'settings.compaction.reminderPercent.help' => '触发"考虑压缩"提醒和提前后台摘要的窗口占比；低于自动层级。',
    'settings.compaction.reminderTokens.help' => '提醒层级的绝对上限：在 min(percentage, this) 时触发。0 表示无上限。',
    'settings.compaction.summaryAssistantChars.help' => '超过此长度的助手回复在启发式摘要行中显示为"[exchanged information]"。',
    'settings.compaction.summaryUserChars.help' => '启发式摘要行保留的用户消息字符数。',
    'settings.compaction.toolOutputChars.help' => '摘要模型可见的压缩对话中助手部分的字符数。',
    'settings.connectTimeoutSeconds.help' => '连接提供程序主机的上限（DNS、TCP、TLS）；非请求超时。',
    'settings.contextPruning.compress.help' => 'manual 仅在你以 /compress 开始的轮次提供 Compress，一次调用；auto 在模型可能修剪的每轮提供。',
    'settings.contextPruning.iterationNudgeThreshold.help' => '自上次提示以来的工具结果数，超过后提醒长工具循环进行修剪。',
    'settings.contextPruning.maxContextTokens.help' => '超过此上下文大小时最新行携带更强的"prune now"提醒。',
    'settings.contextPruning.minContextTokens.help' => '低于此上下文大小时从不提醒模型修剪；不得超过硬提醒大小。',
    'settings.contextPruning.mode.help' => 'auto 在每轮开始时修剪被取代的行；manual 仅在 /sweep 时；off 不显示引用标签。/pruning 可按会话覆盖。',
    'settings.contextPruning.nudgeFrequency.help' => '提醒在上一条之后等待的新行数，避免每步重复。',
    'settings.contextWindow.help' => '令牌窗口覆盖：提供程序模型的数值，或 {"<model>": tokens}。',
    'settings.debug.commands.help' => '将每个被拒绝的自定义命令目录或文件输出到 stderr，而非仅显示启动时的一行计数。',
    'settings.debug.rules.help' => '将每个被拒绝的规则目录或文件输出到 stderr。',
    'settings.debug.skills.help' => '将每个跳过的技能文件和被拒绝的技能目录输出到 stderr，而非仅显示启动时的一行计数。',
    'settings.debug.stream.help' => '当嵌入方的流式接收器在轮次中途失败时，将"onToken observer threw, detaching it"输出到 stderr。',
    'settings.diffPreviewRows.help' => 'Edit 或 Write 差异在转录中显示的完整行数，其余将被摘要。',
    'settings.diffStyle.help' => '转录中的差异布局：`auto` 在宽终端（120 列及以上）上并排显示代码块，其他情况使用统一格式；`unified` 始终单列；`split` 始终双列。两种布局中差异正文按令牌着色；`+`/`-` 标记列保持其颜色。',
    'settings.disabledMcpServers.help' => '`.mcp.json` 中永不启动、列出或调用的服务器名称或通配符（`untrusted_*`），适用于主代理和所有子代理。',
    'settings.disabledRules.help' => '从第一轮起排除在提示之外的用户层级规则包。',
    'settings.disabledSkills.help' => '从发现中移除的技能；优先级高于 enabledSkills。',
    'settings.disabledTools.help' => '从面向模型的工具集中移除的工具名称或通配符。',
    'settings.doubleEscSeconds.help' => '取消运行中轮次时第二次 Esc 必须在第一次后多快按下。',
    'settings.embeddingModel.help' => '每轮记忆召回的嵌入模型；未设置则仅按关键词排序笔记。',
    'settings.enabledSkills.help' => '每轮随系统提示携带完整内容的技能。',
    'settings.env.diffMaxBytes.help' => '两个 git diff 部分各自保留的字节数，超出则截断并附注。',
    'settings.env.gitDiffAfterWrites.help' => '写入文件的步骤后，在轮次上下文中显示已暂存和未暂存的 git diff。',
    'settings.expandToolOutput.help' => '在转录中完整显示每个已完成的工具调用输出；Ctrl+O 或点击仍可折叠。',
    'settings.extraBody.help' => '添加到每个 `custom` 提供程序请求的顶层字段。',
    'settings.formatCommands.help' => '按文件扩展名的编辑后格式化命令（{"php": "vendor/bin/php-cs-fixer fix {file}"}）；在编辑后 lint 之前运行并重写文件。默认关闭。',
    'settings.formatAuto.help' => '当 `formatCommands` 未为某扩展名指定命令时，允许内置扩展表（gofmt、rustfmt、ruff/black、shfmt、terraform fmt、项目自身的 node_modules prettier）格式化编辑后的文件。显式条目优先；项目仍需 `trustedProjectHooks`。默认关闭。',
    'settings.globMaxMatches.help' => '单次 Glob 遍历停止前收集的路径数；输出上限仍约束结果。',
    'settings.grepTimeoutSeconds.help' => '单次 Grep 搜索可运行的秒数，超时则终止；截止前找到的匹配作为部分结果返回。',
    'settings.hooksDefaultTimeoutSeconds.help' => '未设 `timeout:` 的钩子条目可运行的秒数，超时则终止并计为拒绝。',
    'settings.includeGitInstructions.help' => 'Bash 工具的通用提交指南是否随系统提示携带。',
    'settings.instructions.help' => '其内容成为权威系统提示文本的文件通配符。',
    'settings.instructions.walkToRoot.help' => '可选：同时读取最近 .git 标记之上的指令文件，直到但不包括主目录。仅限用户层级；每次读取保持其包含和大小预算。',
    'settings.instructionsExclude.help' => '跳过的指令文件通配符，记录为拒绝；仅限用户层级——仓库不能屏蔽其操作者。检出内的文件按检出相对路径匹配；祖先和强制文件按绝对路径匹配，因此 `**/CLAUDE.local.md` 也能匹配祖先副本。',
    'settings.keybindings.help' => '{"shell.palette": "Ctrl+B"}：为绑定 ID 绑定额外组合键（/keys 参考列出名称）——Ctrl+<key>、Alt+<key>、Shift+<key> 或单独的功能键；出厂组合键仍有效。存在但不可用的键将拒绝启动；出厂绑定请移除该键。',
    'settings.layout.help' => '停靠面板清单；面板移动时由 shell 写入。',
    'settings.lintCommands.help' => '按文件扩展名的编辑后 lint 命令（{"php": "…", "js": false}）；`php -l` 已内置。',
    'settings.lsp.help' => '{"php": {"command": "intelephense", "args": ["--stdio"]}}：用于编辑后诊断、Read 大纲和 Lsp 工具的服务器。',
    'settings.lspAutoDetect.help' => '当项目指纹指定的语言服务器二进制文件在 PATH 中时启动它（composer.json → intelephense、package.json + tsconfig.json → typescript-language-server、pyproject.toml 或 setup.py → pyright-langserver、go.mod → gopls、Cargo.toml → rust-analyzer）；手动 `lsp` 条目按语言优先。启动服务器会运行该服务器及打开树中的构建代码，因此指纹仅在已信任钩子的项目中启动服务器；未信任的根目录不启动任何服务器并在启动通知中记录跳过。',
    'settings.maxCheckpoints.help' => '每会话 /rewind 可回退到的轮次检查点数；超出后最旧的被修剪。',
    'settings.maxCostUsd.help' => '当启动的提供程序报告花费达到此美元数时拒绝新轮次；未设置则无上限。/budget 仅更改当前启动。',
    'settings.maxOutputTokens.help' => '每请求输出上限；未设置则不发送覆盖，使用提供程序默认值。',
    'settings.maxToolSteps.help' => '单轮可进行的提供程序调用数；未设置则保持引擎默认值。',
    'settings.mcp.enabled.help' => '启动受信任项目的 .mcp.json 中指定的 MCP 服务器；off 不启动任何服务器，界面报告启动为已禁用。',
    'settings.mcp.lazySchemaTokens.help' => '单个 MCP 服务器在工具延迟到 mcp_list/mcp_call 之前可声明的模式令牌数；0 表示从不延迟。',
    'settings.mcpResultCapBytes.help' => '单个 MCP 工具回答可传给模型的最大字节数。',
    'settings.memory.autoConsolidate.help' => '将已完成轮次中的持久事实存入记忆，并将压缩日志折叠其中（即 dream pass）；每次均为计费调用。',
    'settings.memory.dreamIntervalSeconds.help' => '同一项目两次 dream pass 之间的最小间隔；每次为计费的只读轮次。',
    'settings.memory.dreamProposeSkills.help' => '允许 dream pass 将技能以草稿形式提议到 ~/.candy-code/skills-proposed；在你通过 /skills 接受前不会生效。',
    'settings.memory.entryMaxBytes.help' => '单条笔记索引行在截断显示前的最大长度；超出则降至用户笔记预算。',
    'settings.memory.projectNoteMaxBytes.help' => '写入仓库 .candy-code/memory/ 时单条项目记忆笔记的最大大小。',
    'settings.memory.promptMaxBytes.help' => '记忆索引笔记行的字节预算；用户笔记预算会相应缩减以适配。',
    'settings.memory.promptMaxEntries.help' => '提示中记忆索引列出的最大笔记数，最新优先；用户笔记计入其中。',
    'settings.memory.userMaxBytes.help' => '用户作用域行的字节预算，包含在总预算内。',
    'settings.memory.userMaxEntries.help' => '优先列出的跨项目（用户作用域）笔记最大数量，计入笔记总数。',
    'settings.modelPrices.help' => '每模型每百万 token 的美元价格（{"input": …, "output": …}），用于支出总额和上限。',
    'settings.models.help' => '各提供商运行的模型（{"<provider>": "<model id>"}）；未设置则使用提供商默认值。',
    'settings.mouse.help' => '向 candy-code 报告鼠标事件（点击、滚轮、选择）；关闭则恢复终端自身的选中即复制。',
    'settings.mouseClicks.help' => '点击和拖拽作用于其命中的对象；关闭则保留滚轮但忽略点击。',
    'settings.notices.transcriptLimit.help' => '以转录行显示的最大启动警告数；其余汇总为一行 "and N more"，stderr 包含全部。',
    'settings.notify.help' => 'off、bell (BEL) 或 osc9（桌面通知）：轮次结束及代理等待审批时发送。',
    'settings.paletteMru.help' => '记住并优先排列的最近使用调色板行数；0 表示不记忆。',
    'settings.parallelToolCalls.help' => '并发执行轮次中的只读工具调用。',
    'settings.parallelToolDeadlineSeconds.help' => '一批并发派发工具调用的挂钟时间上限。',
    'settings.permissionMode.help' => '工具调用的门控方式。绝不从项目文件读取。',
    'settings.permissionRules.help' => '按顺序匹配每个工具调用的 allow / deny / ask 规则。受信任项目的共享 settings.json 可提供 deny / ask 条目——仅可收窄。',
    'settings.permissions.autoAllowReadOnly.help' => '在 default 和 accept-edits 模式下，无需询问即可执行仅含只读命令的 Bash 行（ls、cat、grep、git log、…；无文件重定向、无替换、cd 仅限项目内）。项目只能将其关闭。',
    'settings.permissions.autoStrikeLimit.help' => '在 auto 模式下，同一类别连续被阻止此数量后，下一次变为询问。',
    'settings.permissions.autoTotalLimit.help' => '在 auto 模式下，一次会话中累计阻止此数量后，后续每次阻止均改为询问。',
    'settings.pluginPaths.help' => '除两个已安装根目录外，额外扫描 Claude 格式插件包的目录；值可指向单个包或包含多个包的容器。仅限用户层级——检出的仓库不能注册自身插件。',
    'settings.promptCache.keepWarm.help' => '每段空闲期允许的热身 ping 次数；0（默认）为关闭。每次 ping 重新发送空闲会话的冻结前缀并附带一行指令要求单字符回复，使提供商在 TTL 过期前刷新其提示缓存，从而下一次提示不会以未缓存方式预填整个对话。仅在 cacheTtl 折叠被拒绝时触发——低于其下限或早于其小时——在折叠监视已运行的同一 tick/alarm 上，绝不在轮次中间，绝不同时超过一次，每段空闲期绝不超过此计数。这些是对无人观看会话的计费调用；支出上限仍然生效。计数显示在 /usage 的 `warm` 下。',
    'settings.promptCache.help' => '`vertex` 和 `bedrock` 提供商是否标记提示缓存断点。',
    'settings.promptSuggestionHistory.help' => '提示建议调用中显示的最近消息（每条截断至 2000 字符）。',
    'settings.promptSuggestions.help' => '每轮结束后，询问标题模型你下一条可能发送的消息，并以灰色显示在空输入框中（→ 接受）。',
    'settings.provider.help' => '会话通信的 LLM 提供商；每个提示均发送至其主机。',
    'settings.providerRetryAttempts.help' => '提供商请求瞬时失败（网络、5xx、408、429）时的调用次数，含首次；1 表示从不重试。',
    'settings.providerRetryBaseBackoffMs.help' => '失败的提供商调用首次重试前的等待时间；后续每次等待翻倍。',
    'settings.providers.help' => '按名称的提供商定义（{"<name>": {"type": …, "baseUrl": …, "apiKey": …, "model": …}}）；每个条目叠加在该类型默认值之上。仅限用户层级：项目绝不能改变凭据的发送目标。',
    'settings.queueMode.help' => 'steer（代理在下一步读取）、followup（轮次结束后发送）或 interrupt（在下一步停止轮次后发送）。Tab 始终排队。',
    'settings.readMaxBytes.help' => '单次 Read 调用的上限；下方的页面大小为读取通常返回的大小。',
    'settings.readPageBytes.help' => '单个 Read 页面可容纳的字节数（含行号），无论 `limit` 要求多少。',
    'settings.readPageLines.help' => 'Read 调用未指定 `limit` 时返回的行数。',
    'settings.reasoningEffort.help' => '思考层级在配对决定其形态时发送：openai（o 系列和 gpt-5，不含 -chat 构建）、anthropic 和 vertex（claude-3-7 及更新；vertex 在 claude 和 gemini 两条路径上均响应）、gemini（2.5 及更新）、sglang（每次请求均转发）、bedrock（claude id，作为思考预算）、codex 和 claude-code（命名层级转发至 CLI）；未设置或无法识别则不请求。`/effort` 设置和清除它。',
    'settings.redactToolOutput.help' => '默认关闭：已确定的工具输出按原样保存到 history 和 sessions.db。开启后，每个工具结果在确定后经过与保护记忆和 `/share` 相同的脱敏器——已识别的凭据在持久化字节和后续轮次回放给模型的内容中变为 `[REDACTED]`（工具本身仍原样执行）。图像、文档和用量字段不受影响。`/export` 不添加自身脱敏：它打印存储的确切内容，因此开启前保存的任何内容保持原始状态。',
    'settings.references.help' => '`[{"path": "…", "name": "…"}]` 列表，指定工作区外 Read、Grep、Glob 和 Ls 可只读打开的目录；每个目录在 `<env>` 块中以受限映射展示其内容。Write、Edit 和 Bash 的工作区沙箱不变——引用绝不扩大可写范围。仅限用户层级：检出的仓库不能添加读取根。缺失或非目录路径，或位于会话根内的路径，在启动时拒绝并提示。',
    'settings.repoMap.enabled.help' => '将代码位置映射（包和 PSR-4 源目录）放入系统提示。',
    'settings.repoMap.maxBytes.help' => '仓库映射两个部分各自的字节预算；超出部分仅计数不列出。',
    'settings.requireReadBeforeWrite.help' => '开启后，`Edit`、覆盖已有文件的 `Write`、以及修改/移动/删除文件的 `ApplyPatch` 部分均拒绝执行，直到模型在本会话中读取过该文件；创建新文件永不被阻止。默认关闭：模型已读取的文件无论开关均受磁盘变更规则保护。',
    'settings.resumeCostWarnUsd.help' => '陈旧恢复后，当重新发送历史估计未缓存成本至少为此美元数时，首次提示被暂扣一次；再按 Enter 强制发送，或先执行 /compact。0 禁用暂扣。',
    'settings.sandboxAllowedDomains.help' => '`allowlist` 沙箱可达的主机：纯名称（`example.com`）、`*.example.com` 通配符和 `host:port` 写法（默认：无）。仅在 Linux 上 `bashSandbox` 为 `allowlist` 时使用；列表为空时 `allowlist` 行为与 `no-network` 完全一致。出口代理仅授予 HTTP(S)——未列出的主机一律返回 403，非 HTTP 流量（ssh、数据库端口）失败。格式错误的条目在执行时被忽略：拼写错误只能缩小授权，绝不能扩大。仅限用户层级：检出的仓库不得在其所在沙箱中开洞。macOS 将 `allowlist` 执行为 `no-network`——回环端口分支为已跟踪的后续项。',
    'settings.sandboxScope.help' => '工具路径外哪些命令加入 `bashSandbox` 沙箱：`hooks`、`lint`、`format`、`test`、`lsp`、`mcp`（默认：无）。仅在 `bashSandbox` 非 `off` 时生效——列表说明谁共享沙箱，而非沙箱是否存在。无法识别的条目视为 EVERY scope（最严格，如同无法识别的 `bashSandbox` 值），设置审计会指出。无法启动的沙箱拒绝工作而非放任执行：脚本钩子拒绝，lint、format 和 test 跳过并说明原因，被沙箱化的 LSP 或 MCP stdio 服务器不启动。`lsp` 条目和用户层级 MCP 条目支持每服务器 `"sandbox": false` 退出；项目层级 MCP 退出被忽略。',
    'settings.screenReader.help' => '面向屏幕阅读器用户的呈现方式。开启后，应用去除阅读器无法朗读的装饰——代理加载器固定为单帧静态，方框绘制边框、仅反显的菜单选择等让位于纯文本和听觉提示，每个界面均遵循此开关。关闭则为常规绘制终端。这是你自己的无障碍设置，如同草稿框 vim 模式：检出的项目不能更改。保存后下次读取时生效——实时，无需重载。',
    'settings.rules.standingMaxBytes.help' => '规则文件整体拼接到每个提示中的字节预算（含框架和转义）；超出部分仅以一行指针标注。',
    'settings.scrollWheelLines.help' => '每次滚轮滚动一行转录行数。',
    'settings.sd.apiKey.help' => '发送至 Stable Diffusion 服务器的 Bearer 密钥（若其要求）；优先使用 `${VAR}` 占位符形式而非字面值。',
    'settings.sd.baseUrl.help' => '兼容 AUTOMATIC1111 的 Stable Diffusion webui 的 HTTP 基础 URL（`http://127.0.0.1:7860`）；提示、图像和 API 密钥均从此出口。',
    'settings.sd.defaultModel.help' => '生成请求起始的模型 id；未设置时服务器自行选择。',
    'settings.sd.presets.help' => '媒体表单提供的命名参数包；其结构由媒体管线自身定义，对设置层不透明。',
    'settings.sd.savePattern.help' => '保存媒体的文件名模板；`[date]`、`[time]`、`[seed]` 和 `[number]` 标记在保存时填充。',
    'settings.sd.timeoutSeconds.help' => '单次生成请求在放弃前可运行的秒数；弱 GPU 上的扩散通常需数分钟。',
    'settings.secretEnvAllowlist.help' => 'Bash、Grep 和脚本钩子仍可继承的凭据形态变量名（或通配符）。',
    'settings.server.allowBypass.help' => '服务器会话是否可运行于 bypass-permissions 或 dont-ask 模式（同 --allow-bypass）。',
    'settings.server.allowedHosts.help' => '除回环名称和自身地址外，服务器应答的主机名（或 host:port），如反向代理的地址。',
    'settings.server.allowedIps.help' => '除回环外允许连接的客户端 IP 或 CIDR 范围；其他地址在登录前即被拒绝 403。为空：无地址过滤。',
    'settings.server.allowedOrigins.help' => '除自身外服务器接受的额外浏览器来源（http(s)://host[:port]）。',
    'settings.server.askTimeoutSeconds.help' => '权限询问在拒绝前等待客户端的秒数；0 表示永久等待。',
    'settings.server.browseRoot.help' => 'server.dirBrowse 限定到的目录（同 --browse-root）；未设置则为主目录。',
    'settings.server.dirBrowse.help' => '允许已登录客户端列出 server.browseRoot 下的目录名并在其中启动会话（同 --allow-dir-browse）。默认关闭。',
    'settings.server.clientTools.help' => '允许 Write 作用域客户端通过 tools.client.register 注册工具，使模型可调用在客户端自身运行的代码（client__* 工具）。默认关闭。',
    'settings.server.drainSeconds.help' => '服务器停止前等待运行中轮次的秒数；0 表示立即停止。',
    'settings.server.host.help' => '`serve` 绑定的地址。非回环地址还需启动时指定 --allow-remote。',
    'settings.server.maxConcurrentTurns.help' => '服务器跨会话同时运行的轮次数；超出则拒绝（可重试）。',
    'settings.server.maxOpenSessions.help' => '服务器同时保持打开的会话数；超出则释放最久未使用的空闲会话。',
    'settings.server.port.help' => '`serve` 绑定的端口；0 表示自动选择空闲端口。',
    'settings.server.trustedProxies.help' => '服务器信任其 X-Forwarded-For / X-Forwarded-Proto 的 IP 或 CIDR。',
    'settings.serviceTier.help' => '高级通道在配对决定其形态时发送：openai 在 Chat 和 Responses 两条路径上请求 `service_tier: "priority"`，anthropic 请求 `speed: "fast"`（仅 claude-opus-5-5 GA 系列和 claude-opus-5 / claude-opus-4-8 研究预览系列，其必需的 beta 头自动携带）；未设置或无法识别则不请求。快速模式按高级计费，无法从模型定价表推导：分层配对活跃期间，其轮次以未定价方式记入账本，绝不以猜测费率记录。在启动及每次提供商或模型重建时生效。',
    'settings.sessionRetentionDays.help' => '每次启动删除未命名、未固定且此天数内未触及的会话并列出；0（默认）保留全部。',
    'settings.sessions.autoTitle.help' => '通过一次标题模型调用从首轮为新会话命名；关闭则保持未命名直到 /rename。',
    'settings.sessions.awayRecap.help' => '当你离开三分钟后终端报告焦点恢复时，打印一条会话进度回顾（每次离开一次标题模型调用）；关闭则恢复时静默。`/recap` 可随时请求一条。',
    'settings.skills.listingMaxBytes.help' => '系统提示中整个技能列表的字节预算；超出部分折叠为一行 "N more skills"。',
    'settings.skills.pathNudges.help' => '当工具触及路径作用域技能覆盖的文件时，提醒模型该技能存在，每技能一次。',
    'settings.statusLine.help' => '{"type": "command", "command": "…", "refreshSeconds": 2}：输出绘制状态栏的 shell 命令，每 refreshSeconds 重新运行（2 到 3600，默认 2）。它通过 stdin 接收会话的 JSON 文档（session_id、cwd、model、workspace、version、cost，以及 candy_code 附加字段）；从不读取 stdin 的命令仍会运行。',
    'settings.streamHeaderTimeoutSeconds.help' => '已连接流式服务器发送响应头的最大秒数；绝非请求总超时。',
    'settings.streamIdleTimeoutSeconds.help' => '流式响应单次读取等待字节的超时秒数，超时即判定连接断开；按每次读取计，非总时长。',
    'settings.subagentMaxActive.help' => '单个会话同时可进行的委派运行数，所有层级、成员和后台代理均计入；超出后 `Task` 调用将被拒绝。未设置（默认值）或 0 表示无上限。',
    'settings.subagentMaxConcurrent.help' => '`Task` 单批次中同时执行的调用数（其余等待空闲槽位），以及每个代理池的宽度。未设置（默认）或 0 表示无上限。',
    'settings.subagentMaxDepth.help' => '委托运行可低于会话的层级数；最后一层的运行不会获得 `Task`。设为 1 时，子代理无法继续委托。',
    'settings.subagentMaxTurns.help' => '子代理的步数上限——`Task` 委派、工作流阶段或 `executeAgents` 运行——其预设未声明 `maxTurns`。',
    'settings.subagentModel.help' => '委托子代理在其预设指定 `inherit` 时使用的模型；未设置时沿用会话模型。',
    'settings.summaryModel.help' => '用于生成压缩摘要的模型；未设置时使用对话自身的模型，可复用提示缓存。',
    'settings.symbolMap.enabled.help' => '将按排名排列的符号级仓库映射放入系统提示词，每个会话捕获一次。',
    'settings.temperature.help' => '当请求未指定时，`custom` 提供商发送的采样温度。',
    'settings.terminalBackground.help' => '自适应主题在文本背后的假设：auto 询问终端（OSC 11，然后 COLORFGBG）；light 或 dark 则直接声明。',
    'settings.testCommand.help' => '在项目根目录运行测试的 Shell 命令（`composer test`、`pytest -q`）；`autoTest` 执行的命令。',
    'settings.theme.help' => '颜色主题；/theme 和调色板可实时更改。自定义主题从 ~/.candy-code/themes 下的 JSON 文件加载。',
    'settings.thinkingBudget.help' => '思考令牌预算：`vertex` 提供者的 Gemini `thinkingConfig`；`anthropic` 提供者的扩展思考，Messages API 下限为 1024（0 或未设置表示关闭）。思考令牌按输出计费。',
    'settings.titleModel.help' => '为会话命名并生成提示建议的模型；未设置时使用提供者类型的廉价辅助默认值，优先于块模型。',
    'settings.transcriptJsonl.help' => '将每次提交的对话记录镜像到 `~/.candy-code/transcripts/<project>/` 下的仅追加 JSONL 日志（文件权限 0600），并向钩子脚本传递指向该日志的 `transcript_path` stdin 键。日志保存原始对话且无限增长；启动时读取，因此更改在下次启动时生效。',
    'settings.toolInstructionCapBytes.help' => 'Edit、Write 或 ApplyPatch 结果可携带的 CLAUDE.md/AGENTS.md 正文最大字节数；超出部分以标记截断。',
    'settings.toolOutputCapBytes.help' => 'Bash、Grep、Glob、Lsp 或 WebFetch 结果可传递给模型的最大字节数；截断部分保存至结果指定的文件。',
    'settings.toolOutputPreviewLines.help' => '折叠工具结果在对话记录中显示的行数；Ctrl+O 展开其余部分。',
    'settings.toolSpillCaptureBytes.help' => 'Bash 命令输出（每流）在内存中保留并保存至溢出文件的最大量；不低于输出上限。',
    'settings.toolSpillMinCapBytes.help' => '截断工具结果保存至文件的最小结果上限；低于此值则仅提示截断并丢弃其余部分。',
    'settings.toolSpillWindowPercent.help' => '单个工具结果可占用的上下文窗口最大比例；超出后结果保存至文件，模型仅显示其首尾。',
    'settings.trustedProjectCommands.help' => '允许斜杠命令运行 !`cmd` shell 块的项目根目录。',
    'settings.trustedBundleCommands.label' => '受信任的包命令',
    'settings.trustedBundleCommands.help' => '允许其命令文件运行 !`cmd` shell 块的插件包名称；每条命令仍由权限门裁定。名称须与包自身清单中的名称一致，且仅用户层安装有效——项目的检出不可能自我授予 shell，即便冒用已列出的名称也不行。选择加入不是绕过：权限门只有 Deny 规则会拒绝，被评定为 Ask 的规则将无人值守地执行——展开没有可显示的提示。默认为空，因此包命令不运行 shell。',
    'settings.mcpPromptShell.label' => 'MCP 提示词 shell',
    'settings.mcpPromptShell.help' => '允许其提示词正文运行 !`cmd` shell 块的 MCP 服务器键；每条命令仍由权限门裁定。名称须与您的用户配置赋予服务器的键一致。仅限用户层；默认为空，因此获取的提示词不运行 shell。选择加入不是绕过：权限门只有 Deny 规则会拒绝，被评定为 Ask 的规则将无人值守地执行——展开没有可显示的提示。',
    'settings.trustedProjectHooks.help' => '允许运行 .candy-code/hooks.yaml 的项目根目录。',
    'settings.trustedProjectMcp.help' => '允许启动 .mcp.json 服务器的项目根目录。',
    'settings.trustedProjectSettings.help' => '允许 .candy-code/settings*.json 设置项目层级键的项目根目录。',
    'settings.turnIdleTimeoutSeconds.help' => '运行中的回合无进展可等待的秒数，超时则判定为挂起并停止；空闲时间，非总时长。',
    'settings.ui.imageRenderMode.help' => '生成图像在终端中的渲染方式；`auto` 选择终端报告的最佳协议。',
    'settings.ui.mediaDisplayOverrides.help' => '各渲染模式的显示调整（尺寸上限、回退）；键为渲染模式名称，值为显示参数。',
    'settings.vimMode.help' => '草稿框中的 NORMAL/INSERT 编辑（i a I A o O Esc, h j k l w b e 0 $ x, dd D cc C yy y p P v V, 文本对象 di" da( ciw, 计数 3dd d2w）：NORMAL 模式下的移动、更改、删除和复制，INSERT 模式下的逐字输入。一种模式，非键绑定——不会出现在 /keys 中。保存后下一次按键时生效。',
    'settings.voice.apiKey.help' => '发送至转录端点的 Bearer 密钥（若端点要求）；优先使用 `${VAR}` 占位符形式而非字面值。',
    'settings.voice.baseUrl.help' => 'OpenAI 兼容转录端点的 HTTP 基础 URL（保留尾部 `/v1`）；录音仅发送至该地址。无默认值：在用户层级设置前，语音输入保持关闭。',
    'settings.voice.language.help' => '强制转录语言的 BCP-47 代码（`en`、`de`）；未设置时由端点自动检测。',
    'settings.voice.maxSeconds.help' => '单次录音的硬性秒数上限（5-600，默认 120）。上限随录音器参数传递，因此孤立的录音会自行停止。',
    'settings.voice.model.help' => '每次转录请求发送的模型 ID；`whisper-1` 适用于 OpenAI 兼容端点。',
    'settings.watchFiles.help' => '当保存的文件包含以 AI!（执行更改）或 AI?（回答问题）结尾的注释时发送提示；普通 AI 注释作为上下文附带。聊天空闲时轮询；仅启动后保存的注释触发，且各触发一次。仅限终端会话：监视器运行在终端进程中，因此由 `candy-code serve` 托管的会话不会监视文件。',
    'settings.webFetchMaxBytes.help' => '获取的响应体在内存中保留的最大量；此为内存限制，输出上限才是传递给模型的限制。',
    'settings.webFetchTimeoutSeconds.help' => 'WebFetch socket 读取可停滞的秒数，超时则获取失败。',
    'settings.webSearchBackend.help' => 'WebSearch 查询的搜索服务：`searxng`（默认）将所有查询发送至配置的 `webSearchEndpoint`；`brave`、`tavily` 和 `exa` 连接该服务的固定主机，且各自需要环境变量中的 API 密钥（`BRAVE_SEARCH_API_KEY`、`TAVILY_API_KEY`、`EXA_API_KEY`），无法指向其他 URL。',
    'settings.webSearchEndpoint.help' => '受信任的 SearXNG 实例搜索 URL（`https://searx.example.org/search`）；所有 WebSearch 查询均发送至该地址。',
    'settings.webSearchMaxResults.help' => 'WebSearch 摘要列出的结果数，每条含标题、URL 和摘要片段。',
    'settings.webSearchTimeoutSeconds.help' => '单次搜索请求可耗费的秒数。',
    'settings.webhooks.help' => '钩子名称到 {secret, prompt, permissionMode?, rate?} 的映射；POST /api/hooks/{name} 将请求体（转义为不可信）拼入提示并启动后台会话。为空（默认）则不挂载任何内容。rate 为每地址每分钟及每钩子总体的投递次数。启动时拒绝钩子的 bypass-permissions；无模式的钩子以服务器模式与默认模式中更严格者运行。条目还可指定 signature: {scheme: "github-sha256"|"hmac-sha256", header?, deliveryHeader?}：路由通过签名头使用条目密钥验证原始请求体的 HMAC-SHA256（sha256=<hex>），替代自定义头密钥，因为 GitHub 无法发送自定义头；签名失败计入同一钩子锁定，已见过的投递 ID（GitHub 方案默认使用 X-GitHub-Delivery；通用方案使用配置的 deliveryHeader）返回 {"ok": true, "duplicate": true} 而不启动第二个会话。',
    'settings.webhooksOut.help' => '端点名称到 {url, secret, events} 的映射；events 为从 turn.completed、session.ended、permission.asked 和 schedule.fired 中选取的非空列表。为空（默认）则不开放任何出站。仅从 USER 层级读取——项目或捆绑配置永远无法添加出站端点。url 必须为 https，仅当字面主机为 localhost 或回环地址时允许 http，且绝不携带 userinfo；secret 至少 16 个字符，以 HMAC-SHA256 对每次投递签名作为 X-Candy-Code-Signature（对精确请求体的 sha256=<hex>）并搭配 X-Candy-Code-Timestamp。投递在事件循环上异步执行——调度永不等待响应：2 秒连接边界和每次 POST 10 秒网络上限约束每次投递（webhook 边界，非 LLM 请求超时），传输失败和 5xx 响应按 2/8/30 秒重试阶梯递增，4xx 和重定向响应首次即为最终（因为拒绝而非跟随重定向），128 个在途投递的有界队列在溢出时丢弃新调度而非增长内存。启动时读取；更改映射在重启后生效。',
    'settings.webhooksOut.refuse' => '用户配置中的 webhooksOut 不可用：{reason}。拒绝启动而非向未完全验证的端点投递——修复映射，或移除该键以在无出站 webhook 的情况下运行。',
    // --- end settings help ---

